from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON file; top-level object or array is legal."""
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    try:
        data = json.loads(text)
    except ValueError:
        raise ValueError('invalid JSON payload: ' + str(p))
    if not isinstance(data, (dict, list)):
        raise ValueError('payload top-level must be object or array: ' + str(p))
    return data

