    except ValueError:
        raise ValueError('invalid JSON payload: ' + str(p))
    if not isinstance(data, (dict, list)):
        raise ValueError('payload top-level must be object or array: ' + str(p))
    return data

def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError('payloads must be a list')
    if len(payloads) != len(contract.get('inputs', [])):
        raise ValueError('payload count must match contract inputs')
    data = payloads[0]
    if not isinstance(data, dict):
        raise ValueError('claims input must be an object')
    if 'old' not in data or 'new' not in data:
        raise ValueError('claims input requires old and new')
    old = data['old']
    new = data['new']
    if not isinstance(old, list) or not isinstance(new, list):
        raise ValueError('old and new must be lists')

    def parse_fields(fields):
        result = {}
        for f in fields:
            if not isinstance(f, dict):
                raise ValueError('field entries must be objects')
            if 'name' not in f or 'type' not in f or 'required' not in f:
                raise ValueError('field entry requires name, type, required')
            name = f['name']
            if type(name) is not str or name.strip() == '':
                raise ValueError('name must be non-empty string')
            name = name.strip()
            typ = f['type']
            if typ not in ('int', 'float', 'str', 'bool'):
                raise ValueError('type must be int/float/str/bool')
            required = f['required']
            if type(required) is not bool:
                raise ValueError('required must be boolean')
            has_default = 'default' in f
            if name in result:
                raise ValueError('duplicate normalized field name')
            result[name] = {'type': typ, 'required': required, 'has_default': has_default}
        return result

    old_fields = parse_fields(old)
    new_fields = parse_fields(new)

    changes = []
    for name in sorted(set(old_fields) | set(new_fields)):
        in_old = name in old_fields
        in_new = name in new_fields
        if in_old and not in_new:
            changes.append({'field': name, 'code': 'removed', 'breaking': True})
        elif in_new and not in_old:
            nf = new_fields[name]
            changes.append({
                'field': name,
                'code': 'added',
                'breaking': nf['required'] is True and not nf['has_default'],
            })
        else:
            of = old_fields[name]
            nf = new_fields[name]
            if of['type'] != nf['type']:
                breaking = not (of['type'] == 'int' and nf['type'] == 'float')
                changes.append({'field': name, 'code': 'type', 'breaking': breaking})
            if of['required'] is False and nf['required'] is True:
                changes.append({'field': name, 'code': 'required', 'breaking': not nf['has_default']})

    compatible = all(not c['breaking'] for c in changes)
    return {'name': contract['name'], 'result': {'compatible': compatible, 'changes': changes}}

