    return type(v) is int


def _nonempty_str(v):
    return type(v) is str and v.strip() != ''


def _has_revoked_ancestor(token, tokens, revoked):
    cur = token
    while cur is not None:
        if cur in revoked:
            return True
        t = tokens.get(cur)
        if t is None:
            break
        cur = t.get('parent')
    return False


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError('payloads must be a list')
    if len(payloads) != len(contract.get('inputs', [])):
        raise ValueError('payload count must match contract inputs')
    for p in payloads:
        _check_finite(p)

