    if not isinstance(data, dict):
        raise ValueError('sessions input must be an object')
    if 'now' not in data:
        raise ValueError('sessions input requires now')
    now = data['now']
    if not _is_int(now) or now < 0:
        raise ValueError('now must be an int >= 0')
    if 'events' not in data:
        raise ValueError('sessions input requires events')
    events = data['events']
    if not isinstance(events, list):
        raise ValueError('events must be a list')

    seen_ids = set()
    issued_tokens = set()
    parsed = []
    for ev in events:
        if not isinstance(ev, dict):
            raise ValueError('event entries must be objects')
        if 'id' not in ev:
            raise ValueError('event requires id')
        eid = ev['id']
        if type(eid) not in (str, int, float) or (isinstance(eid, float) and not math.isfinite(eid)):
            raise ValueError('event id must be a finite scalar')
        if eid in seen_ids:
            raise ValueError('duplicate event id')
        seen_ids.add(eid)
        if 'ts' not in ev:
            raise ValueError('event requires ts')
        ts = ev['ts']
        if not _is_int(ts) or ts < 0:
            raise ValueError('event ts must be an int >= 0')
        if 'kind' not in ev:
            raise ValueError('event requires kind')
        kind = ev['kind']
        if kind not in ('issue', 'refresh', 'revoke'):
            raise ValueError('event kind must be issue/refresh/revoke')
        if 'token' not in ev:
            raise ValueError('event requires token')
        token = ev['token']
        if not _nonempty_str(token):
            raise ValueError('token must be a non-empty string')

