            if 'subject' not in ev:
                raise ValueError('issue event requires subject')
            subject = ev['subject']
            if not _nonempty_str(subject):
                raise ValueError('subject must be a non-empty string')
            if 'expires' not in ev:
                raise ValueError('issue event requires expires')
            expires = ev['expires']
            if not _is_int(expires) or expires <= ts:
                raise ValueError('issue expires must be an int > ts')
            if 'groups' not in ev:
                raise ValueError('issue event requires groups')
            groups = ev['groups']
            if not isinstance(groups, list):
                raise ValueError('groups must be a list')
            for g in groups:
                if not _nonempty_str(g):
                    raise ValueError('group must be a non-empty string')
            if token in issued_tokens:
                raise ValueError('token may only be issued or refreshed once')
            issued_tokens.add(token)
