import math
from fnmatch import fnmatchcase


def _check_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError('non-finite number in payload')
    elif isinstance(obj, dict):
        for v in obj.values():
            _check_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _check_finite(v)


def _nonempty_str(v):
    return type(v) is str and v.strip() != ''


def _unwrap(p):
    if isinstance(p, dict) and set(p.keys()) == {'name', 'result'}:
        return p['result']
    return p


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError('payloads must be a list')
    if len(payloads) != len(contract.get('inputs', [])):
        raise ValueError('payload count must match contract inputs')
    for p in payloads:
        _check_finite(p)

    objects = [_unwrap(p) for p in payloads]
    if len(objects) != 3:
        raise ValueError('federation_authorize requires three inputs')

    auth = objects[0]
    schema_result = objects[1]
    session_result = objects[2]
    if not isinstance(auth, dict):
        raise ValueError('authorization input must be an object')
    if 'groups' not in auth or 'rules' not in auth or 'requests' not in auth:
        raise ValueError('authorization input requires groups, rules, requests')
    groups = auth['groups']
    rules = auth['rules']
    requests = auth['requests']
    if not isinstance(groups, list) or not isinstance(rules, list) or not isinstance(requests, list):
        raise ValueError('groups, rules and requests must be lists')

    group_map = {}
    for g in groups:
        if not isinstance(g, dict):
            raise ValueError('group entries must be objects')
        if 'id' not in g or 'parents' not in g or 'roles' not in g:
            raise ValueError('group entry requires id, parents, roles')
        gid = g['id']
        if not _nonempty_str(gid):
            raise ValueError('group id must be a non-empty string')
        if gid in group_map:
            raise ValueError('duplicate group id')
        parents = g['parents']
        if not isinstance(parents, list):
            raise ValueError('group parents must be a list')
        for p in parents:
            if not _nonempty_str(p):
                raise ValueError('group parent must be a non-empty string')
        roles = g['roles']
        if not isinstance(roles, list):
            raise ValueError('group roles must be a list')
        for r in roles:
            if not _nonempty_str(r):
                raise ValueError('group role must be a non-empty string')
        group_map[gid] = {'parents': list(parents), 'roles': list(roles)}

    for gid, g in group_map.items():
        for p in g['parents']:
            if p not in group_map:
                raise ValueError('unknown parent group')

    rule_list = []
    for r in rules:
        if not isinstance(r, dict):
            raise ValueError('rule entries must be objects')
        if 'id' not in r or 'role' not in r or 'resource' not in r or 'action' not in r or 'effect' not in r:
            raise ValueError('rule entry requires id, role, resource, action, effect')
        rid = r['id']
        if not _nonempty_str(rid):
            raise ValueError('rule id must be a non-empty string')
        if any(x['id'] == rid for x in rule_list):
            raise ValueError('duplicate rule id')
        role = r['role']
        if not _nonempty_str(role):
            raise ValueError('rule role must be a non-empty string')
        resource = r['resource']
        if not _nonempty_str(resource):
            raise ValueError('rule resource must be a non-empty string')
        action = r['action']
        if not _nonempty_str(action):
            raise ValueError('rule action must be a non-empty string')
        effect = r['effect']
        if effect not in ('allow', 'deny'):
            raise ValueError('rule effect must be allow/deny')
        rule_list.append({
            'id': rid,
            'role': role,
            'resource': resource,
            'action': action,
            'effect': effect,
        })

    request_list = []
    for r in requests:
        if not isinstance(r, dict):
            raise ValueError('request entries must be objects')
        if 'id' not in r or 'token' not in r or 'resource' not in r or 'action' not in r:
            raise ValueError('request entry requires id, token, resource, action')
        rid = r['id']
        if not _nonempty_str(rid):
            raise ValueError('request id must be a non-empty string')
        if any(x['id'] == rid for x in request_list):
            raise ValueError('duplicate request id')
        token = r['token']
        if not _nonempty_str(token):
            raise ValueError('request token must be a non-empty string')
        resource = r['resource']
        if not _nonempty_str(resource):
            raise ValueError('request resource must be a non-empty string')
        action = r['action']
        if not _nonempty_str(action):
            raise ValueError('request action must be a non-empty string')
        request_list.append({'id': rid, 'token': token, 'resource': resource, 'action': action})

    if not isinstance(schema_result, dict) or 'compatible' not in schema_result:
        raise ValueError('schema result requires compatible')
    compatible = schema_result['compatible']
    if type(compatible) is not bool:
        raise ValueError('schema compatible must be boolean')

    if not isinstance(session_result, dict) or 'active_tokens' not in session_result:
        raise ValueError('session result requires active_tokens')
    active_tokens = session_result['active_tokens']
    if not isinstance(active_tokens, list):
        raise ValueError('active_tokens must be a list')
    active_map = {}
    for t in active_tokens:
        if not isinstance(t, dict):
            raise ValueError('active token entries must be objects')
        if 'token' not in t or 'groups' not in t:
            raise ValueError('active token requires token and groups')
        tok = t['token']
        if not _nonempty_str(tok):
            raise ValueError('active token name must be a non-empty string')
        grps = t['groups']
        if not isinstance(grps, list):
            raise ValueError('active token groups must be a list')
        for g in grps:
            if not _nonempty_str(g):
                raise ValueError('active token group must be a non-empty string')
        active_map[tok] = list(grps)

    # Unknown groups referenced by active tokens are input errors regardless of schema.
    for tok, grps in active_map.items():
        for g in grps:
            if g not in group_map:
                raise ValueError('unknown group in active token')

    def closure_roles(gid):
        reachable = set()
        stack = [gid]
        while stack:
            cur = stack.pop()
            if cur in reachable:
                continue
            reachable.add(cur)
            for p in group_map[cur]['parents']:
                if p not in reachable:
                    stack.append(p)
        roles = set()
        for g in reachable:
            roles.update(group_map[g]['roles'])
        return roles

    decisions = []
    allow_count = 0
    deny_count = 0

    if not compatible:
        for req in request_list:
            decisions.append({
                'id': req['id'],
                'effect': 'deny',
                'reason': 'schema',
                'rule_id': None,
                'roles': [],
            })
            deny_count += 1
    else:
        for req in request_list:
            token = req['token']
            if token not in active_map:
                decisions.append({
                    'id': req['id'],
                    'effect': 'deny',
                    'reason': 'session',
                    'rule_id': None,
                    'roles': [],
                })
                deny_count += 1
                continue

            roles = set()
            for g in active_map[token]:
                roles.update(closure_roles(g))
            roles_sorted = sorted(roles)

            matching_allow = []
            matching_deny = []
            for rule in rule_list:
                if (rule['role'] in roles
                        and fnmatchcase(req['resource'], rule['resource'])
                        and fnmatchcase(req['action'], rule['action'])):
                    if rule['effect'] == 'deny':
                        matching_deny.append(rule['id'])
                    else:
                        matching_allow.append(rule['id'])

            if matching_deny:
                effect = 'deny'
                reason = 'rule'
                rule_id = min(matching_deny)
            elif matching_allow:
                effect = 'allow'
                reason = 'rule'
                rule_id = min(matching_allow)
            else:
                effect = 'deny'
                reason = 'default'
                rule_id = None

            decisions.append({
                'id': req['id'],
                'effect': effect,
                'reason': reason,
                'rule_id': rule_id,
                'roles': roles_sorted,
            })
            if effect == 'allow':
                allow_count += 1
            else:
                deny_count += 1

    return {
        'name': contract['name'],
        'result': {
            'decisions': decisions,
            'allow': allow_count,
            'deny': deny_count,
        },
    }

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def find_contracts():
    return sorted(
        p for p in ROOT.rglob('contract.json')
        if 'outputs' not in p.relative_to(ROOT).parts
    )


def load_contract(path):
    return json.loads(path.read_text(encoding='utf-8'))


def execution_order(contracts):
    output_owner = {}
    for cp in contracts:
        c = load_contract(cp)
        output_owner[c['output']] = cp

    deps = {}
    for cp in contracts:
        c = load_contract(cp)
        ds = set()
        for inp in c.get('inputs', []):
            owner = output_owner.get(inp)
            if owner is not None and owner != cp:
                ds.add(owner)
        deps[cp] = ds

    result = []
    remaining = set(contracts)
    while remaining:
        ready = sorted(
            (cp for cp in remaining if deps[cp] <= set(result)),
            key=lambda p: str(p),
        )
        if not ready:
            raise ValueError('cycle in component dependencies')
        cp = ready[0]
        result.append(cp)
        remaining.remove(cp)
    return result


def main():
    contracts = find_contracts()
    if not contracts:
        raise ValueError('no component contracts')
    for cp in execution_order(contracts):
        render = cp.with_name('render.py')
        subprocess.run([sys.executable, str(render)], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / 'integrate.py')], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / 'final_report.py')], cwd=ROOT, check=True)


if __name__ == '__main__':
    main()

